// Verify one exact QQ polynomial row/cofactor identity; classify its image
// using ONLY the supplied localization factors. CLI row cofactor units.
#include <flint/fmpq_mpoly.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cassert>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&q):Poly(){fmpq_mpoly_set(p,q.p,ctx);}Poly(Poly&&q):Poly(){fmpq_mpoly_swap(p,q.p,ctx);}Poly&operator=(Poly q){fmpq_mpoly_swap(p,q.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void rd(istream&f,Poly&p){long nt;f>>nt;assert(f&&nt>=0);fmpq_t c;fmpq_init(c);ulong ex[3];for(long j=0;j<nt;j++){string s;f>>s>>ex[0]>>ex[1]>>ex[2];assert(f&&!fmpq_set_str(c,s.c_str(),10));fmpq_canonicalise(c);fmpq_mpoly_push_term_fmpq_ui(p.p,c,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);assert(fmpq_mpoly_length(p.p,ctx)==nt);fmpq_clear(c);}
int main(int argc,char**argv){assert(argc==4);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{ifstream in(argv[1]),units(argv[2]);ofstream out(argv[3]);int n,m,k;in>>n>>m>>k;assert(n==1);int discard;for(int i=0;i<k+n;i++)in>>discard;vector<Poly>A(m);for(auto&q:A)rd(in,q);const char*names[]={"a","e","d"};vector<Poly>known;string text;while(getline(units,text))if(!text.empty()){Poly q;assert(!fmpq_mpoly_set_str_pretty(q.p,text.c_str(),names,ctx));known.push_back(q);}assert(known.size()==3);out<<"1 "<<m<<" 0\n";ulong ex[3];fmpq_t c,content;fmpq_init(c);fmpq_init(content);long terms=0,nb=0,db=0,degree=0;cout<<"[";
for(int i=0;i<m;i++){Poly q=A[i],quot,factor,tmp;fmpq_mpoly_one(factor.p,ctx);vector<int>vals;for(auto&u:known){int v=0;while(!fmpq_mpoly_is_zero(q.p,ctx)&&fmpq_mpoly_divides(quot.p,q.p,u.p,ctx)){q=quot;fmpq_mpoly_mul(tmp.p,factor.p,u.p,ctx);factor=tmp;v++;}vals.push_back(v);}if(!fmpq_mpoly_is_zero(q.p,ctx)){fmpq_set(content,fmpq_mpoly_content_ref(q.p,ctx));fmpq_mpoly_scalar_div_fmpq(q.p,q.p,content,ctx);fmpq_mpoly_scalar_mul_fmpq(factor.p,factor.p,content,ctx);fmpq_mpoly_mul(tmp.p,q.p,factor.p,ctx);assert(fmpq_mpoly_equal(tmp.p,A[i].p,ctx));}else fmpq_one(content);int z=fmpq_mpoly_length(q.p,ctx);out<<z;terms+=z;degree=max(degree,fmpq_mpoly_total_degree_si(q.p,ctx));for(int j=0;j<z;j++){fmpq_mpoly_get_term_coeff_fmpq(c,q.p,j,ctx);fmpq_mpoly_get_term_exp_ui(ex,q.p,j,ctx);char*cs=fmpq_get_str(nullptr,10,c);out<<' '<<cs;flint_free(cs);for(int v:ex)out<<' '<<v;nb=max(nb,(long)fmpz_bits(fmpq_numref(c)));db=max(db,(long)fmpz_bits(fmpq_denref(c)));}out<<'\n';if(i)cout<<',';char*cs=fmpq_get_str(nullptr,10,content);cout<<"{\"column\":"<<i<<",\"QQ_content\":\""<<cs<<"\",\"powers_a_P_J\":["<<vals[0]<<','<<vals[1]<<','<<vals[2]<<"]}";flint_free(cs);}cout<<"]\n";cerr<<"TERMS "<<terms<<" NUM_BITS "<<nb<<" DEN_BITS "<<db<<" DEGREE "<<degree<<" EXACT_ALL_COLUMN_IDENTITIES_PASS\n";fmpq_clear(c);fmpq_clear(content);}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
